# sitemap URLs
sitemap=root/'sitemap.xml'
s=sitemap.read_text(encoding='utf-8')
for f in ['anime-fashion-week.html', *hubs.keys()]:
    url=f'https://anioracle.online/{f}'
    if url not in s:
        s=s.replace('</urlset>', f'  <url><loc>{url}</loc><changefreq>weekly</changefreq><priority>0.8</priority></url>\n</urlset>')
    sitemap.write_text(s,encoding='utf-8')
